UPDATE experiment_run r SET control_state = 'PAUSE_REQUESTED', pause_requested_at = now(), pause_kind = #{kind}, pause_reason = #{reason} FROM experiment e WHERE r.tenant_id = #{tenantId} AND e.tenant_id = r.tenant_id AND e.id = r.experiment_id AND r.status IN ('queued', 'running') AND r.control_state = 'NONE'
AND e.island_id = #{scopeId}
AND r.experiment_id = #{scopeId}
